                        {formatMoney(3.99)} fee
                      </span>
                    </Button>
                    <Button
                      type="button"
                      variant={!isDelivery ? 'primary' : 'outline-primary'}
                      aria-pressed={!isDelivery}
                      onClick={() => setOrderType('CARRYOUT')}
                    >
                      Pick up
