  const [addresses, setAddresses] = useState<Address[]>([]);
  const [selectedAddressId, setSelectedAddressId] = useState<string>(NEW_ADDRESS);

  // Saved cards, for signed-in customers. Offered on the payment step; empty means "new card only".
  const [cards, setCards] = useState<PaymentMethod[]>([]);

  const [form, setForm] = useState({
    customerName: user?.fullName ?? '',
    email: user?.email ?? '',
    phone: '',
    addressLine1: '',
    city: '',
    state: '',
    postalCode: '',
  });

  const isDelivery = orderType === 'DELIVERY';
  // Only ask for typed address fields when there is no saved address selected.
  const usingNewAddress = selectedAddressId === NEW_ADDRESS;

  /*
   * Load the customer's saved addresses and preselect their PRIMARY one.
   *
   * Guests skip this entirely — they have no account, so there is nothing to load.
   */
  useEffect(() => {
    if (!isAuthenticated) return;

    let cancelled = false;
    profileApi
      .listAddresses()
      .then((saved) => {
        if (cancelled) return;
        setAddresses(saved);

        const primary = saved.find((a) => a.primary) ?? saved[0];
        if (primary) {
          setSelectedAddressId(primary.id);
          setForm((current) => ({
            ...current,
            phone: current.phone || (primary.phone ?? ''),
          }));
        }
      })
      .catch(() => {
        // A profile that will not load must not block checkout — fall back to typing an address.
      });

    return () => {
      cancelled = true;
    };
  }, [isAuthenticated]);

  /*
   * Load the customer's saved cards, for the payment step.
   *
   * Same shape as the address load above, and the same rule: guests skip it, and a list that will
   * not load must not block checkout — the payment step simply offers a new card.
   */
  useEffect(() => {
    if (!isAuthenticated) return;

    let cancelled = false;
    profileApi
      .listPaymentMethods()
      .then((saved) => {
        if (!cancelled) setCards(saved);
      })
      .catch(() => {
        // Fall back to the new-card form.
      });

    return () => {
      cancelled = true;
    };
  }, [isAuthenticated]);

