        return {
          addressLine1: chosen.line1,
          addressLine2: chosen.line2 ?? undefined,
          city: chosen.city,
          state: chosen.state,
          postalCode: chosen.postalCode,
        };
      }
    }
    return {
      addressLine1: form.addressLine1,
      city: form.city,
      state: form.state,
      postalCode: form.postalCode,
    };
  }

