// TEMPORARY — step 5 manual verification. Deleted after the run; step 6 writes the real spec.
import { expect, test } from '@playwright/test';
import type { APIRequestContext, Page } from '@playwright/test';

const API = 'http://localhost:8085';

test.describe.configure({ mode: 'serial' });

async function token(request: APIRequestContext) {
  const r = await request.post(`${API}/api/auth/login`, {
    data: { email: 'customer@pizza.test', password: 'pizza123' },
  });
  return (await r.json()).token as string;
}

async function saveCard(request: APIRequestContext, pm: string) {
  const r = await request.post(`${API}/api/me/payment-methods`, {
    headers: { Authorization: `Bearer ${await token(request)}` },
    data: { stripePaymentMethodId: pm },
  });
  expect(r.status(), await r.text()).toBe(201);
}

async function deleteAllCards(request: APIRequestContext) {
  const auth = { Authorization: `Bearer ${await token(request)}` };
  const cards = await (await request.get(`${API}/api/me/payment-methods`, { headers: auth })).json();
  for (const c of cards) await request.delete(`${API}/api/me/payment-methods/${c.id}`, { headers: auth });
}

async function signInAndReachPaymentStep(page: Page) {
  await page.goto('/login');
  await page.getByLabel('Email').fill('customer@pizza.test');
  await page.getByLabel('Password').fill('pizza123');
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect(page.getByRole('button', { name: /Demo Customer/ })).toBeVisible();

  await page.goto('/menu?type=PIZZA');
  await page
    .getByRole('heading', { name: 'Pepperoni Pizza', exact: true })
    .locator('xpath=ancestor::div[contains(@class,"product-card")]')
    .getByRole('button', { name: 'Build it' })
    .click();
  await page.getByRole('dialog').locator('label[for="size-LARGE"]').click();
  await page.getByRole('dialog').getByRole('button', { name: 'Add to cart' }).click();
  await page.getByRole('button', { name: /Open cart/ }).click();
  await page.getByRole('button', { name: 'Checkout' }).click();
  await page.getByRole('button', { name: /Continue to payment/ }).click();
  await expect(page.getByText(/is reserved/)).toBeVisible({ timeout: 15_000 });
  return (await page.locator('code').first().textContent())!.trim();
}

test.beforeEach(async ({ request }) => deleteAllCards(request));
test.afterEach(async ({ request }) => deleteAllCards(request));

test('A: primary preselected, button label, pays, confirmation shows PAID + card', async ({ page, request }) => {
  test.setTimeout(90_000);
  await saveCard(request, 'pm_card_visa');
  const orderId = await signInAndReachPaymentStep(page);

  await expect(page.getByLabel(/Visa ••4242/)).toBeChecked();
  const pay = page.getByRole('button', { name: /^Pay \$\d+\.\d\d with Visa ••4242$/ });
  await expect(pay).toBeVisible({ timeout: 20_000 });
  await pay.click();

  await expect(page).toHaveURL(new RegExp(`/order-confirmation/${orderId}`), { timeout: 30_000 });
  await expect(page.getByText(/visa/i).filter({ hasText: /4242/ }).first()).toBeVisible({ timeout: 30_000 });
  const order = await (await request.get(`${API}/api/orders/${orderId}/payment-status`)).json();
  expect(order.status).toBe('PAID');
  expect(order.cardLast4).toBe('4242');
  console.log('A order', orderId, order.status, order.cardBrand, order.cardLast4);
});

test('B: decline shown, then a second saved card pays the SAME order', async ({ page, request }) => {
  test.setTimeout(90_000);
  await saveCard(request, 'pm_card_chargeCustomerFail'); // first → primary
  await saveCard(request, 'pm_card_visa');
  const orderId = await signInAndReachPaymentStep(page);

  await page.getByRole('button', { name: /^Pay .* with Visa ••0341$/ }).click({ timeout: 20_000 });
  await expect(page.getByRole('alert')).toContainText(/declined/i, { timeout: 30_000 });
  await expect(page).toHaveURL(/\/checkout/);
  console.log('B decline message:', await page.getByRole('alert').textContent());

  await page.getByLabel(/Visa ••4242/).check();
  await page.getByRole('button', { name: /^Pay .* with Visa ••4242$/ }).click();
  await expect(page).toHaveURL(new RegExp(`/order-confirmation/${orderId}`), { timeout: 30_000 });
  const order = await (await request.get(`${API}/api/orders/${orderId}/payment-status`)).json();
  expect(order.status).toBe('PAID');
  console.log('B order', orderId, order.status, order.cardLast4);
});

test('C: 3D Secure card brings up the challenge', async ({ page, request }) => {
  test.setTimeout(90_000);
  await saveCard(request, 'pm_card_authenticationRequired');
  const orderId = await signInAndReachPaymentStep(page);

  await page.getByRole('button', { name: /^Pay .* with Visa ••3184$/ }).click({ timeout: 20_000 });
  const challenge = page.frameLocator('iframe[name^="__privateStripeFrame"]').first();
  await expect(page.locator('iframe[name^="__privateStripeFrame"]').first()).toBeVisible({ timeout: 30_000 });
  await page.screenshot({ path: '/tmp/step5-3ds.png' });

  // Try to complete Stripe's test challenge; record what happens either way.
  try {
    const inner = challenge.frameLocator('iframe[name="stripe-challenge-frame"], #challengeFrame').first();
    await inner.getByRole('button', { name: /complete/i }).click({ timeout: 15_000 });
    await expect(page).toHaveURL(new RegExp(`/order-confirmation/${orderId}`), { timeout: 30_000 });
    console.log('C 3DS completed; order', orderId);
  } catch (e) {
    console.log('C 3DS challenge shown but could not be completed headlessly:', String(e).split('\n')[0]);
  }
});

test('D: expired card shown, disabled and labelled (stubbed list)', async ({ page }) => {
  test.setTimeout(60_000);
  await page.route('**/api/me/payment-methods', (route) =>
    route.fulfill({
      json: [
        { id: '11111111-0000-4000-8000-000000000001', brand: 'visa', last4: '1111', expMonth: 1, expYear: 2020, primary: true },
        { id: '11111111-0000-4000-8000-000000000002', brand: 'mastercard', last4: '4444', expMonth: 12, expYear: 2099, primary: false },
      ],
    }),
  );
  await signInAndReachPaymentStep(page);

  const expired = page.getByLabel(/Visa ••1111/);
  await expect(expired).toBeDisabled({ timeout: 20_000 });
  await expect(expired).not.toBeChecked();
  await expect(page.getByText('Expired', { exact: true })).toBeVisible();
  // Primary is expired, so the first usable card is preselected instead.
  await expect(page.getByLabel(/Mastercard ••4444/)).toBeChecked();
  await expect(page.getByRole('button', { name: /with Mastercard ••4444$/ })).toBeVisible();
});

